type TelemetryEvent = {
  tenant_id: string;
  user_id_hash: string;
  model_id: string;
  prompt_type: string;
  latency_ms: number;
  token_count: number;
  bias_score: number;
  safety_flag: boolean;
  timestamp: string;
}
```

